import { useEffect, useState } from 'react';
import type * as React from 'react';
import { Link, Route, Switch, useLocation, useParams } from 'wouter';
import {
  Activity, ArrowLeft, BarChart3, BookOpen, CalendarDays, Check, CheckCircle2,
  ChevronRight, CircleHelp, Download, FileJson, Filter, Gauge, History,
  LayoutDashboard, Lightbulb, MoreHorizontal, Pencil, Plus, RotateCcw,
  Search, Settings, ShieldCheck, Sparkles, Sun, Moon, Trash2, TrendingUp, Upload,
  X, Zap,
} from 'lucide-react';

type ThemeMode = 'light' | 'dark' | 'system';
type AttendanceStatus = 'present' | 'absent';
type Subject = { id: string; name: string; code: string; color: string; attended: number; total: number; target: number };
type AttendanceRecord = { id: string; subjectId: string; date: string; status: AttendanceStatus; note?: string };
type AppData = { subjects: Subject[]; records: AttendanceRecord[]; theme: ThemeMode };
type ModalState = { type: 'subject' | 'confirm-delete-subject' | 'confirm-clear-history' | 'confirm-reset' | 'import-error'; subject?: Subject; message?: string } | null;

const STORAGE_KEY = 'bunkmaster-data-v1';
const DEFAULT_TARGET = 85;
const colors = ['#f27b5b', '#7a8fd0', '#82b5a4', '#c99c55', '#9a7bc4', '#5ca7b0'];
const pct = (attended: number, total: number) => total ? Math.round((attended / total) * 1000) / 10 : 0;
const missable = (s: Subject) => s.target >= 100 ? 0 : Math.max(0, Math.floor(s.attended / (s.target / 100) - s.total));
const needed = (s: Subject) => {
  if (!s.total || pct(s.attended, s.total) >= s.target) return 0;
  const ratio = s.target / 100;
  return Math.max(0, Math.ceil((ratio * s.total - s.attended) / (1 - ratio)));
};
const formatDate = (date: string) => new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(date));
const todayLabel = () => new Intl.DateTimeFormat('en-US', { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date());
const initials = (name: string) => name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase();
const validImport = (value: unknown): value is Pick<AppData, 'subjects' | 'records'> => {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as { subjects?: unknown; records?: unknown };
  if (!Array.isArray(candidate.subjects) || !Array.isArray(candidate.records)) return false;
  return candidate.subjects.every((item) => {
    if (!item || typeof item !== 'object') return false;
    const subject = item as Partial<Subject>;
    return typeof subject.id === 'string' && typeof subject.name === 'string' && typeof subject.code === 'string' &&
      typeof subject.color === 'string' && typeof subject.attended === 'number' && typeof subject.total === 'number' &&
      typeof subject.target === 'number' && subject.attended >= 0 && subject.total >= subject.attended && subject.target > 0 && subject.target <= 100;
  }) && candidate.records.every((item) => {
    if (!item || typeof item !== 'object') return false;
    const record = item as Partial<AttendanceRecord>;
    return typeof record.id === 'string' && typeof record.subjectId === 'string' && typeof record.date === 'string' &&
      (record.status === 'present' || record.status === 'absent');
  });
};

function loadInitial(): AppData {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) return { theme: 'light', subjects: [], records: [], ...JSON.parse(raw) };
  } catch { /* private storage can be cleared at any time */ }
  return { theme: 'light', subjects: [], records: [] };
}

function useBunkData() {
  const [data, setData] = useState<AppData>(loadInitial);
  const [modal, setModal] = useState<ModalState>(null);
  const [toast, setToast] = useState('');
  const [lastUndo, setLastUndo] = useState<AppData | null>(null);
  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }, [data]);
  useEffect(() => {
    const resolved = data.theme === 'system' ? (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light') : data.theme;
    document.documentElement.classList.toggle('dark', resolved === 'dark');
    localStorage.setItem('bunkmaster-theme-v1', data.theme);
  }, [data.theme]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 2800); return () => window.clearTimeout(timer); }, [toast]);
  const addSubject = (input: Omit<Subject, 'id'>) => { setLastUndo(null); setData((current) => ({ ...current, subjects: [...current.subjects, { ...input, id: crypto.randomUUID() }] })); setModal(null); setToast('Subject added. You are back in control.'); };
  const editSubject = (id: string, input: Omit<Subject, 'id'>) => { setLastUndo(null); setData((current) => ({ ...current, subjects: current.subjects.map((item) => item.id === id ? { ...input, id } : item) })); setModal(null); setToast('Subject details updated.'); };
  const deleteSubject = (id: string) => { setLastUndo(null); setData((current) => ({ ...current, subjects: current.subjects.filter((item) => item.id !== id), records: current.records.filter((item) => item.subjectId !== id) })); setModal(null); setToast('Subject removed.'); };
  const markAttendance = (subjectId: string, status: AttendanceStatus) => {
    const subject = data.subjects.find((item) => item.id === subjectId);
    if (!subject) return;
    setLastUndo(data);
    setData((current) => ({ ...current, subjects: current.subjects.map((item) => item.id === subjectId ? { ...item, total: item.total + 1, attended: item.attended + (status === 'present' ? 1 : 0) } : item), records: [{ id: crypto.randomUUID(), subjectId, date: new Date().toISOString(), status }, ...current.records] }));
    setToast(status === 'present' ? `${subject.name} marked present.` : `${subject.name} marked missed.`);
  };
  const undoAttendance = () => {
    if (!lastUndo) return;
    setData(lastUndo);
    setLastUndo(null);
    setToast('Last attendance check-in undone.');
  };
  const clearHistory = () => { setLastUndo(null); setData((current) => ({ ...current, records: [] })); setModal(null); setToast('History cleared. Your totals stay intact.'); };
  const reset = () => { setLastUndo(null); setData({ theme: data.theme, subjects: [], records: [] }); setModal(null); setToast('Fresh slate. Nothing leaves your device.'); };
  return { data, setData, modal, setModal, toast, addSubject, editSubject, deleteSubject, markAttendance, undoAttendance, lastUndo, clearHistory, reset };
}

const navItems = [
  { href: '/', label: 'Today', icon: LayoutDashboard },
  { href: '/subjects', label: 'Subjects', icon: BookOpen },
  { href: '/history', label: 'History', icon: History },
  { href: '/insights', label: 'Insights', icon: BarChart3 },
  { href: '/settings', label: 'Settings', icon: Settings },
];

